import type { PageId } from '@/config/site';
import type { ContentFile, PageMeta } from './types';

// Generated by `npm run content` (git-ignored). Each page has a small meta file for the top of the
// page and a big content file; both are lazy chunks, loaded separately.
const files = import.meta.glob<ContentFile>('./generated/*.json', { import: 'default' });

function load<T>(key: string, what: string, id: string): Promise<T> {
  const loader = files[`./generated/${key}.json`];
  if (!loader) {
    return Promise.reject(new Error(`No generated ${what} for "${id}". Run \`npm run content\`.`));
  }
  return loader() as Promise<T>;
}

export function loadPageContent(id: PageId): Promise<ContentFile> {
  return load<ContentFile>(id, 'content', id);
}

export function loadPageMeta(id: PageId): Promise<PageMeta> {
  return load<PageMeta>(`${id}.meta`, 'meta', id);
}
